const legacy2022PageByRoute = new Map(
  legacy2022Pages.map((page) => [page.route, page])
);

export function getLegacy2022Page(route: string): Legacy2022Page {
  const normalizedRoute = route.endsWith('/') ? route : `${route}/`;
  const page = legacy2022PageByRoute.get(normalizedRoute);

  if (!page) {
    throw new Error(`Missing PyCon HK 2022 page: ${route}`);
  }

  return page;
}
